def related_users_to_contacts(apps, schema_editor):
    """Older entries pointed at any app user; give each owner a private contact with that person's name."""
    Expense = apps.get_model("workmanager", "Expense")
    ExpenseContact = apps.get_model("workmanager", "ExpenseContact")
    for expense in Expense.objects.filter(related_user__isnull=False, contact__isnull=True).select_related("related_user"):
        user = expense.related_user
        name = (getattr(user, "full_name", "") or user.email or f"User {user.pk}").strip()[:150]
        contact, _ = ExpenseContact.objects.get_or_create(owner_id=expense.owner_id, name=name)
        expense.contact = contact
        expense.save(update_fields=["contact"])


